    description: "Encode and decode text with ITA2, the International Telegraph Alphabet No. 2 — the 5-bit character code best known as Baudot, used by teleprinters from the 1920s through early computers and news-wire services. Each character is a 5-bit code (only 32 codes), too few for letters and digits, so ITA2 uses two character sets toggled by shift codes: LTRS (11111) for letters and FIGS (11011) for figures (digits and punctuation), like a typewriter's Shift Lock. The encoder emits a shift only when the set changes; the decoder tracks the current set. Encode text to its 5-bit teleprinter codes and back, with an optional per-code annotation and the full LTRS/FIGS table shown for reference. Space, CR, and LF are shared by both sets and need no shift. Pairs with the Bacon, Tap Code, Morse Code, and ASCII tools. Everything runs locally in your browser.",
